def fichero_artifacts_get_region(
    *,
    artifact_id: Annotated[str, Field(description='Artifact Id')],
    char_end: Annotated[Optional[int], Field(description="End offset (exclusive) into the artifact's content")] = None,
    char_start: Annotated[Optional[int], Field(description="Start offset into the artifact's content")] = None,
    line: Annotated[Optional[int], Field(description="Zero-based line of the artifact's content")] = None,
) -> Any:
    'Get Artifact Region\n\nResolve a line or character span of a transcription to its page region.\n\nThis is the single addressing scheme #4418 asks for: a region, a text span\nand a claim all name the same thing through character offsets into the\nartifact\'s content. Resolution lives here rather than in each client so\nthere is one answer to "where did this line come from" — two answers would\nbe worse than none for archival material.\n\nSpans are resolved against the artifact\'s CONTENT, which is what the reader\nis reading, not against the geometry record\'s own copy of the text.\n\nRoute: GET /api/artifacts/{artifact_id}/region (toolset `artifacts`; reads).'
    return _rt.call("GET", f"/api/artifacts/{artifact_id}/region", params={"char_end": char_end, "char_start": char_start, "line": line})


def fichero_artifacts_edit_regions(
    *,
    artifact_id: Annotated[str, Field(description='Artifact Id')],
    bbox: Annotated[Optional[list[Any]], Field(description='Normalized [x, y, w, h] for move/add.')] = None,
    indices: Annotated[Optional[list[Any]], Field(description='Positions into ocr_geometry.boxes (order irrelevant)')] = None,
    level: Annotated[Optional[str], Field(description='OCRGeometryLevel. One of: page, block, line, word, region.')] = None,
    op: Annotated[str, Field(description='A closed vocabulary — an enum in the schema, never a bare str (rule 4). One of: move, delete, add, combine.')],
    text: Annotated[Optional[str], Field(description='Text for the new box on `add`. REFUSED on add until readings attach to segments (422, `TextNeedsReadings`): once a page\'s boxes are segment records there is nowhere lawful to keep typed words, and a page\'s first edit converts it (#4924). Draw the region, then transcribe it. Ignored by the other ops. Default: "".')] = None,
) -> Any:
    "Edit Artifact Regions\n\nCurate an artifact's regions: move, delete, add, or combine boxes.\n\nCuration-grade: one audited, undoable action per edit — nothing is ever\nlost.\n\nBefore a page's first edit, each edit is also appended to the block's\n`curation_log`. The first edit converts the page to segment records;\nfrom then on the block is never written, and the history is each\nsegment's versions and the audit record (#4924).\n\nRoute: PUT /api/artifacts/{artifact_id}/regions (toolset `artifacts`; changes data, as the agent account when one exists)."
    return _rt.call("PUT", f"/api/artifacts/{artifact_id}/regions", json=_rt.body({"bbox": bbox, "indices": indices, "level": level, "op": op, "text": text}))


