def fichero_authz_revoke_library_member_role(
    *,
    user: Annotated[str, Field(description='User')],
) -> Any:
    "Revoke Library Member Role\n\nRevoke a member's whole-library role — typed surface over ``acl.set``\nremove. Same owner-gated, audited, change-stream path as the generic\n``POST /api/actions/invoke``; an owner cannot revoke their own role.\nReturns the refreshed member list.\n\nRoute: DELETE /api/authz/members (toolset `authz`; changes data, as the agent account when one exists)."
    return _rt.call("DELETE", "/api/authz/members", params={"user": user})


def fichero_authz_list_library_members(
) -> Any:
    "List Library Members\n\nWho can access this library, roles joined with account profiles.\n\nOwner-gated when multi-user is on (mirrors the snapshot's ``can_manage_roles``).\nThe ``roles`` table keys on the *normalized* library path, so normalize the\ntransport header before the lookup or the join silently returns empty.\n\nRoute: GET /api/authz/members (toolset `authz`; reads)."
    return _rt.call("GET", "/api/authz/members")


def fichero_authz_set_library_member_role(
    *,
    role: Annotated[str, Field(description='owner/editor/viewer.')],
    user: Annotated[str, Field(description='Target user id or username.')],
) -> Any:
    'Set Library Member Role\n\nAssign/change a library role — typed surface over the ``acl.set`` action.\n\nRoutes through ``registry.invoke`` so the mutation is owner-gated, audited,\nand emitted on the change stream exactly like ``POST /api/actions/invoke``.\nReturns the refreshed member list so the UI updates in one round-trip.\n\nRoute: PUT /api/authz/members (toolset `authz`; changes data, as the agent account when one exists).'
    return _rt.call("PUT", "/api/authz/members", json=_rt.body({"role": role, "user": user}))


def fichero_authz_share_library_object(
    *,
    object_id: Annotated[Optional[str], Field(description='Entity/document id (required for those types)')] = None,
    object_type: Annotated[Optional[str], Field(description='library | entity | document. Default: "library".')] = None,
    role: Annotated[Optional[str], Field(description='Role to grant: owner/editor/viewer. Default: "viewer".')] = None,
    user: Annotated[str, Field(description='Recipient user id or username.')],
) -> Any:
    'Share Library Object\n\nShare a library / entity / document (#1867) — the authz-gated model.\n\nGrants the recipient a per-library role through the audited ``acl.set``\naction (owner-gated, emits authz.changed) and returns an engine link to the\nobject. Entity/document shares grant library access so the recipient can\nreach the object (the ACL is per-library); those types require an object_id.\n\nRoute: POST /api/authz/share (toolset `authz`; changes data, as the agent account when one exists).'
    return _rt.call("POST", "/api/authz/share", json=_rt.body({"object_id": object_id, "object_type": object_type, "role": role, "user": user}))


