def fichero_claim_links_update(
    *,
    link_id: Annotated[str, Field(description='Link Id')],
    evidence: Annotated[Optional[str], Field(description='Evidence.')] = None,
    link_quality: Annotated[Optional[float], Field(description='Link Quality.')] = None,
    metadata: Annotated[Optional[dict[str, Any]], Field(description='Metadata.')] = None,
    relation_type: Annotated[Optional[str], Field(description="Typed relationship kinds for KnowledgeClaimLink (#1123 Phase B). Originally four kinds (supports / contradicts / refines / duplicate_of). #1123 extends with five new dimensions plus ``related_to`` (the generic fallback used by ``kg_predictions._record_predictions`` when a model surfaces a relation outside the curated set): - ``corroborates`` — independent evidence agreeing with the source claim. Distinct from ``supports`` (which just reinforces with additional evidence drawn from the same line of reasoning). - ``derives_from`` — claim B is inferred from / built on claim A; removing A invalidates B. Stronger than ``cites``. - ``cites`` — B references A as a source. Bibliographic / citation graph use. - ``follows`` — temporal sequence (A then B). Doesn't imply causation; ``caused_by`` is the explicit causal claim. - ``caused_by`` — A is the cause of B. Strong claim; reviewers should treat with corroboration. - ``related_to`` — generic fallback when the typed kinds don't fit. Closes the latent crash in ``kg_predictions.py:269`` where the relation_map fallback referenced this value before it existed. Note: ``contests`` was considered as a synonym for ``contradicts`` but excluded — same semantic, different word, doesn't earn a separate enum slot. Writers should keep using ``contradicts``. One of: supports, contradicts, refines, duplicate_of, corroborates, derives_from, cites, follows, caused_by, related_to.")] = None,
) -> Any:
    'Update Claim Link\n\nUpdate an existing claim link.\n\nRoute: PATCH /api/claim-links/{link_id} (toolset `claim-links`; changes data, as the agent account when one exists).'
    return _rt.call("PATCH", f"/api/claim-links/{link_id}", json=_rt.body({"evidence": evidence, "link_quality": link_quality, "metadata": metadata, "relation_type": relation_type}))


