def fichero_claim_links_create(
    *,
    claim_id: Annotated[str, Field(description='Claim Id')],
    evidence: Annotated[Optional[str], Field(description='Evidence.')] = None,
    link_quality: Annotated[Optional[float], Field(description='Link Quality. Default: 0.5.')] = None,
    metadata: Annotated[Optional[dict[str, Any]], Field(description='Metadata.')] = None,
    related_claim_id: Annotated[str, Field(description='Related Claim Id.')],
    relation_type: Annotated[str, Field(description="Typed relationship kinds for KnowledgeClaimLink (#1123 Phase B). Originally four kinds (supports / contradicts / refines / duplicate_of). #1123 extends with five new dimensions plus ``related_to`` (the generic fallback used by ``kg_predictions._record_predictions`` when a model surfaces a relation outside the curated set): - ``corroborates`` — independent evidence agreeing with the source claim. Distinct from ``supports`` (which just reinforces with additional evidence drawn from the same line of reasoning). - ``derives_from`` — claim B is inferred from / built on claim A; removing A invalidates B. Stronger than ``cites``. - ``cites`` — B references A as a source. Bibliographic / citation graph use. - ``follows`` — temporal sequence (A then B). Doesn't imply causation; ``caused_by`` is the explicit causal claim. - ``caused_by`` — A is the cause of B. Strong claim; reviewers should treat with corroboration. - ``related_to`` — generic fallback when the typed kinds don't fit. Closes the latent crash in ``kg_predictions.py:269`` where the relation_map fallback referenced this value before it existed. Note: ``contests`` was considered as a synonym for ``contradicts`` but excluded — same semantic, different word, doesn't earn a separate enum slot. Writers should keep using ``contradicts``. One of: supports, contradicts, refines, duplicate_of, corroborates, derives_from, cites, follows, caused_by, related_to.")],
) -> Any:
    'Create Claim Link\n\nCreate a link between two claims.\n\nRoute: POST /api/claims/{claim_id}/links (toolset `claim-links`; changes data, as the agent account when one exists).'
    return _rt.call("POST", f"/api/claims/{claim_id}/links", json=_rt.body({"evidence": evidence, "link_quality": link_quality, "metadata": metadata, "related_claim_id": related_claim_id, "relation_type": relation_type}))


