def fichero_segments_compare_readings(
    *,
    document_id: Annotated[str, Field(description='Document Id')],
    hypothesis: Annotated[dict[str, Any], Field(description='One reading of the page: a pass, or a saved result (artifact).')],
    policies: Annotated[Optional[list[Any]], Field(description='normalisation policies: accent-blind, diplomatic, layout-insensitive, lenient.')] = None,
    reference: Annotated[dict[str, Any], Field(description='One reading of the page: a pass, or a saved result (artifact).')],
    reference_checked_by: Annotated[Optional[str], Field(description='who checked the reference; without it the score is agreement, not CER.')] = None,
) -> Any:
    "Compare Readings\n\nHow far one reading of this page is from another, by Fichero's CER definition, under each\nnormalisation policy asked for. Labelled `agreement` unless `reference_checked_by` names who\nchecked the reference. Refuses (422) rather than returning a number it cannot stand behind:\nan empty reference, an unknown policy, a text too long for an exact score.\n\nRoute: POST /api/documents/{document_id}/readings/compare (toolset `segments`; changes data, as the agent account when one exists)."
    return _rt.call("POST", f"/api/documents/{document_id}/readings/compare", json=_rt.body({"hypothesis": hypothesis, "policies": policies, "reference": reference, "reference_checked_by": reference_checked_by}))


def fichero_renditions_list(
    *,
    document_id: Annotated[str, Field(description='Document Id')],
) -> Any:
    'List Renditions\n\nEvery rendition of one node, in display order.\n\n404s on a missing document rather than returning an empty list: "this node\nhas no renditions" and "this node does not exist" are different answers,\nand a client that cannot tell them apart will render an empty flip strip\nfor a typo\'d id and call it a page with one image.\n\nAn existing node with no renditions is a legitimate empty list — folders\nhave none, and neither does a node whose bytes were never materialised.\n\nRoute: GET /api/documents/{document_id}/renditions (toolset `renditions`; reads).'
    return _rt.call("GET", f"/api/documents/{document_id}/renditions")


def fichero_renditions_get_content(
    *,
    document_id: Annotated[str, Field(description='Document Id')],
    rendition_id: Annotated[str, Field(description='Rendition Id')],
) -> Any:
    'Get Rendition Content\n\nServe one rendition\'s pixels.\n\nWithout this a client can list a page\'s renditions and name them but never\nSHOW one, because `Rendition.path` is a server-side path and the standing\nrule is that visuals travel over storage endpoints — the engine may be on\nanother machine, so a path is not something a client can open.\n\nEvery failure is a 404 on purpose, and the reasons are deliberately not\ndistinguished to the caller: separating "no such rendition" from "belongs\nto another document" from "outside the permitted roots" would let a caller\nprobe for the existence of ids and paths it has no grant for. The\ndistinction that IS meaningful to a client — no such document versus a\ndocument with no renditions — is already answered by the list route above.\n\nThe path is confined by `resolve_document_source_path`, the same authority\nthe IIIF image route uses. Its contract is that the path comes from a\nRECORD reached by id and never from the caller, which is exactly the case\nhere: `rendition_id` selects a row, and only that row\'s stored path is\nresolved. The client never supplies a path.\n\nRoute: GET /api/documents/{document_id}/renditions/{rendition_id}/content (toolset `renditions`; reads).'
    return _rt.image("GET", f"/api/documents/{document_id}/renditions/{rendition_id}/content")


def fichero_documents_rollup(
    *,
    document_id: Annotated[str, Field(description='Document Id')],
) -> Any:
    "Cheap per-type child counts for a collapsed library outline row\n\nReturns per-type child counts (artifacts, entities, notes, claims, pages) for a document, rolled up over the document and every descendant page/chunk. The library Table renders these on a *collapsed* outline row so it can show 'N entities, M notes' without fetching the children; the heavier per-type payloads are loaded only when the disclosure is expanded (#2258).\n\nThis is intentionally cheap — plain counts with no entity resolution, dedup, or merge-chain walking. The ``entities`` count therefore mirrors the inspector's union (entities linked by this document's claims plus entities whose per-page scope intersects the document) and is NOT the deduped/merge-resolved figure from /knowledge-graph. ``pages`` counts descendant page documents only (not the document itself).\n\nRoute: GET /api/documents/{document_id}/rollup (toolset `documents`; reads)."
    return _rt.call("GET", f"/api/documents/{document_id}/rollup")


