    journal_or_book: Annotated[Optional[str], Field(description='Journal Or Book.')] = None,
    kind: Annotated[Optional[str], Field(description='Standard BibTeX entry types for first-class references. One of: article, book, booklet, inbook, incollection, inproceedings, manual, mastersthesis, misc, phdthesis, proceedings, techreport, unpublished.')] = None,
    language: Annotated[Optional[str], Field(description='Language.')] = None,
    metadata: Annotated[Optional[dict[str, Any]], Field(description='Metadata.')] = None,
