def fichero_search_streaming(
    *,
    compile: Annotated[Optional[bool], Field(description='Compile. Default: false.')] = None,
    filters: Annotated[Optional[dict[str, Any]], Field(description='Filters.')] = None,
    highlight_results: Annotated[Optional[bool], Field(description='Highlight Results. Default: true.')] = None,
    include: Annotated[Optional[list[Any]], Field(description='Include.')] = None,
    limit: Annotated[Optional[int], Field(description='Limit. Default: 10.')] = None,
    min_score: Annotated[Optional[float], Field(description='Min Score. Default: 0.55.')] = None,
    offset: Annotated[Optional[int], Field(description='Offset. Default: 0.')] = None,
    query: Annotated[str, Field(description='Query.')],
    search_type: Annotated[Optional[str], Field(description='Search Type. Default: "hybrid".')] = None,
    sort_by: Annotated[Optional[str], Field(description='Sort By. Default: "relevance".')] = None,
    sort_direction: Annotated[Optional[str], Field(description='Sort Direction. Default: "desc".')] = None,
    use_fuzzy_match: Annotated[Optional[bool], Field(description='Use Fuzzy Match. Default: false.')] = None,
) -> Any:
    'Streaming Search\n\nStreaming search v1 (#4604, Daniel\'s ruling Q11: streaming IS in\nscope) — results appear as they are found, newline-delimited JSON:\n\n    {"type": "provisional", "leg": "fulltext", "results": [...]}\n    {"type": "final", "results": [...], "total_count": N, "stats": {...}}\n\nPhase 1 re-runs only the cheap keyword leg (~tens of ms) so exact\nmatches paint immediately; phase 2 is the full hybrid ranking, which\nREPLACES the provisional list. A failed phase streams\n{"type": "error", "detail": ...} — never a silently truncated stream.\n\nRoute: POST /api/search/stream (toolset `search`; changes data, as the agent account when one exists).'
    return _rt.call("POST", "/api/search/stream", json=_rt.body({"compile": compile, "filters": filters, "highlight_results": highlight_results, "include": include, "limit": limit, "min_score": min_score, "offset": offset, "query": query, "search_type": search_type, "sort_by": sort_by, "sort_direction": sort_direction, "use_fuzzy_match": use_fuzzy_match}))


def fichero_segments_list_in_scope(
    *,
    document_ids: Annotated[Optional[str], Field(description="Comma-separated document ids to list segments for. Either this or `parent_id`; `parent_id` resolves to a folder's descendants.")] = None,
    include_furniture: Annotated[Optional[bool], Field(description='Include running heads, folio numbers and catchwords')] = None,
    kind: Annotated[Optional[str], Field(description='Restrict to one segment kind (region, line, word, ...)')] = None,
    limit: Annotated[Optional[int], Field(description='Page size; bounded on purpose')] = None,
    offset: Annotated[Optional[int], Field(description='Offset')] = None,
    parent_id: Annotated[Optional[str], Field(description='A folder (or page-bearing document): its descendants are the scope')] = None,
    pass_id: Annotated[Optional[str], Field(description='Restrict to one pass')] = None,
) -> Any:
    "List Segments In Scope\n\n`GET /api/segments` — a bounded page of segments across a SCOPE.\n\nFor `source.editor.library-lists-segments` (#4941): every other segments read is\nper document or per segment, so a Library listing segments would have had to ask\nonce per page of the book. That is the N+1 the one-store seam exists to avoid,\nand moving it into the engine is the only way a project-wide list of lines is\nanswerable at all.\n\nOnly REAL rows. The per-document route also serves the old boxes of artifacts\nnobody has converted (`source.seam.read-either-store`), and that resolution is\nper artifact by nature — it reads one artifact's block and numbers its boxes.\nDoing it across a scope would mean hydrating every geometry blob in the folder to\nanswer one page, which is the cost this endpoint exists to avoid. So a scoped list\nshows what has been converted, and says so here rather than appearing to show\neverything.\n\n`limit` is capped at 1000 by the signature (`source.store.bounded-reads`): a\ncaller cannot ask for a whole project in one request, because a page of a library\nview never needs it and an agent asking for it would be asking for the thing that\ntakes the engine down.\n\nRoute: GET /api/segments (toolset `segments`; reads)."
    return _rt.call("GET", "/api/segments", params={"document_ids": document_ids, "include_furniture": include_furniture, "kind": kind, "limit": limit, "offset": offset, "parent_id": parent_id, "pass_id": pass_id})


def fichero_segments_update_many(
    *,
    updates: Annotated[list[Any], Field(description='Updates.')],
) -> Any:
    "Update Segments Many\n\n`PATCH /api/segments` — one attribute edit across a selection, as one audited\naction and one undo step. Answers the new versions AND the audit id, so the app can\noffer ⌘Z for the whole edit without guessing which row to invert.\n\nPATCH on the collection, not `POST /update-many`: a partial modification of some of\nthe collection's members is what PATCH means, and `check_rest_conventions` requires\nan `update_*` operation to be PUT or PATCH. The body carries `expected_version`s, and\nPATCH — unlike DELETE — carries a body reliably, which is the invariant that matters.\n\nRoute: PATCH /api/segments (toolset `segments`; changes data, as the agent account when one exists)."
    return _rt.call("PATCH", "/api/segments", json=_rt.body({"updates": updates}))


def fichero_segments_create(
    *,
    anchor: Annotated[dict[str, Any], Field(description='Where a record points on a page — the one anchor type. Used by annotations, OCR geometry, entity mentions, claim evidence and content representations. One type means one overlay renderer, one hit tester, one "scroll to this", and one place to get the coordinate maths right. ``rendition_id`` is the field whose absence caused the original defect: a box carried four numbers and never said which pixel frame they were fractions OF, so geometry computed on an enhanced or split rendition was drawn over the original spread. It is optional only so existing rows stay readable — new writes must set it whenever the frame is not the node\'s own.')],
    baseline: Annotated[Optional[list[Any]], Field(description='Baseline.')] = None,
    document_id: Annotated[str, Field(description='Document Id.')],
    kind: Annotated[str, Field(description='Kind.')],
    kind_raw: Annotated[Optional[str], Field(description='Kind Raw.')] = None,
    parent_segment_id: Annotated[Optional[str], Field(description='Parent Segment Id.')] = None,
    pass_id: Annotated[str, Field(description='Pass Id.')],
) -> Any:
    'Create Segment\n\nRoute: POST /api/segments (toolset `segments`; changes data, as the agent account when one exists).'
    return _rt.call("POST", "/api/segments", json=_rt.body({"anchor": anchor, "baseline": baseline, "document_id": document_id, "kind": kind, "kind_raw": kind_raw, "parent_segment_id": parent_segment_id, "pass_id": pass_id}))


