def fichero_training_start_kraken(
    *,
    base: Annotated[Optional[str], Field(description='The Kraken reader to start from (a model id); none trains from nothing.')] = None,
    batch_size: Annotated[Optional[int], Field(description="Lines per step, as on this Mac; none: the largest measured to fit the hardware's GPU (8 on a 16 GB T4), else ketos's 16.")] = None,
    display_name: Annotated[Optional[str], Field(description='Display Name.')] = None,
    flavor: Annotated[Optional[str], Field(description='Hugging Face hardware. Default: "t4-small".')] = None,
    held_out_ids: Annotated[Optional[list[Any]], Field(description='Pages kept home as the test; never sent.')] = None,
    name: Annotated[Optional[str], Field(description='A short name for the trained reader\'s file. Default: "reader".')] = None,
    not_for_release: Annotated[Optional[bool], Field(description='The trained model may not be released. Default: true.')] = None,
    pages_may_leave: Annotated[Optional[bool], Field(description="The person's yes for these pages to go to Hugging Face. Default: false.")] = None,
    release_note: Annotated[Optional[str], Field(description='Release Note.')] = None,
    scope_ids: Annotated[list[Any], Field(description='Folders or pages whose teacher-read lines are the lessons.')],
    teacher: Annotated[str, Field(description='The model whose line readings are the lessons, e.g. google/gemini-3-flash-preview.')],
    timeout: Annotated[Optional[str], Field(description='The Job\'s time limit; always sent (the service\'s default is 30 minutes). Default: "4h".')] = None,
) -> Any:
    "Train a Kraken reader on Hugging Face Jobs\n\nQueue a `train-a-model` job: the pages in scope whose lines the teacher read go to a private\nbucket of the person's Hugging Face account, Fichero's trainer fine-tunes the base reader there,\nand the trained reader comes home as a reader card. Refused (and nothing queued) without the\nperson's yes for the pages to leave, without a Hugging Face token, or with a base reader that is\nnot installed.\n\nRoute: POST /api/training/kraken (toolset `training`; changes data, as the agent account when one exists)."
    return _rt.call("POST", "/api/training/kraken", json=_rt.body({"base": base, "batch_size": batch_size, "display_name": display_name, "flavor": flavor, "held_out_ids": held_out_ids, "name": name, "not_for_release": not_for_release, "pages_may_leave": pages_may_leave, "release_note": release_note, "scope_ids": scope_ids, "teacher": teacher, "timeout": timeout}))


def fichero_training_start_kraken_here(
    *,
    base: Annotated[Optional[str], Field(description='The Kraken reader to start from (a model id); none trains from nothing.')] = None,
    batch_size: Annotated[Optional[int], Field(description='Lines per step; small keeps memory down on a 16 GB Mac. Default: 4.')] = None,
    display_name: Annotated[Optional[str], Field(description='Display Name.')] = None,
    epochs: Annotated[Optional[int], Field(description='A fixed number of epochs; none stops when it stops improving.')] = None,
    held_out_ids: Annotated[Optional[list[Any]], Field(description='Pages kept home as the test; never sent.')] = None,
    name: Annotated[Optional[str], Field(description='A short name for the trained reader\'s file. Default: "reader".')] = None,
    not_for_release: Annotated[Optional[bool], Field(description='The trained model may not be released. Default: true.')] = None,
    pages_may_leave: Annotated[Optional[bool], Field(description="The person's yes for these pages to go to Hugging Face. Default: false.")] = None,
    release_note: Annotated[Optional[str], Field(description='Release Note.')] = None,
    scope_ids: Annotated[list[Any], Field(description='Folders or pages whose teacher-read lines are the lessons.')],
    teacher: Annotated[str, Field(description='The model whose line readings are the lessons, e.g. google/gemini-3-flash-preview.')],
) -> Any:
    'Train a Kraken reader on this Mac, gently\n\nQueue a `train-on-this-mac` job: the same training set and settings as the Hugging Face card,\ntrained here on the local-model lane. Nothing leaves this Mac. It holds while the Mac is in use,\nhot or on battery, lets memory go and comes back when memory is tight or other work is waiting,\nresumes from its last finished epoch, and records the memory and time it took. Follow and stop it\nwith `/training/jobs/{job_id}`. Refused with a base reader that is not installed.\n\nRoute: POST /api/training/kraken/here (toolset `training`; changes data, as the agent account when one exists).'
    return _rt.call("POST", "/api/training/kraken/here", json=_rt.body({"base": base, "batch_size": batch_size, "display_name": display_name, "epochs": epochs, "held_out_ids": held_out_ids, "name": name, "not_for_release": not_for_release, "pages_may_leave": pages_may_leave, "release_note": release_note, "scope_ids": scope_ids, "teacher": teacher}))


