def fichero_training_start_gathering_reasons(
    *,
    checked: Annotated[str, Field(description='The model id of the CHECKED pass (its lines and their right readings).')],
    held_out_ids: Annotated[Optional[list[Any]], Field(description='Pages kept as the test: never asked about.')] = None,
    language: Annotated[Optional[str], Field(description='Language.')] = None,
    model: Annotated[str, Field(description='The teacher: a reasoning vision model, e.g. Qwen3-VL-8B-Thinking.')],
    prompt_file: Annotated[Optional[str], Field(description="The recipe's prompt file; none uses Fichero's own.")] = None,
    provider: Annotated[str, Field(description="The teacher's provider, e.g. openrouter, gemini, omlx.")],
    scope_ids: Annotated[list[Any], Field(description='Folders or pages whose checked lines are asked about.')],
) -> Any:
    "Ask a palaeographer for its reasons (or review) on each checked line\n\nQueue a `gather-reasons` job (#4642): the teacher (a reasoning vision model) reads every line of\nthe checked pass in scope, held-out pages left out, and gives the letterforms, abbreviations and\nuncertain readings behind each reading. Each call is an episode in the ledger; the vision card's\n`why` and `thinking` arms are made from them (the `review` arm from the check job's readings card,\n`POST /api/check/runs`). A hosted teacher goes through the egress gate like any model call.\n\nRoute: POST /api/training/reasons (toolset `training`; changes data, as the agent account when one exists)."
    return _rt.call("POST", "/api/training/reasons", json=_rt.body({"checked": checked, "held_out_ids": held_out_ids, "language": language, "model": model, "prompt_file": prompt_file, "provider": provider, "scope_ids": scope_ids}))


def fichero_training_start_reasons_ab(
    *,
    checked: Annotated[str, Field(description='The model id of the CHECKED pass: the right readings.')],
    contenders: Annotated[list[Any], Field(description='The answer-only student, the reasoning students, the teacher and a cheap baseline.')],
    held_out_ids: Annotated[list[Any], Field(description='The held-out checked pages: no arm trained on them.')],
    language: Annotated[Optional[str], Field(description='Language.')] = None,
    noise_band: Annotated[Optional[float], Field(description='A reasoning student is adopted only if it beats the answer-only one by more than this CER. Default: 0.005.')] = None,
) -> Any:
    "Measure answer-only against reasoning students on held-out checked pages\n\nQueue a `reasons-ab` job (#4642, `distill.reasoning.ab-decides`): every contender reads the held-out\nchecked lines as it was trained (a reasoning student also with its reasoning off); one CER and WER\neach, seconds a line, and for a `why` student whether its errors fall where it said it was unsure. A\nreasoning student is adopted only beyond `noise_band`; the result is written on every Fichero-trained\ncontender's card either way. Through `training.measure_reasons_ab`; 422 without held-out pages.\n\nRoute: POST /api/training/reasons-ab (toolset `training`; changes data, as the agent account when one exists)."
    return _rt.call("POST", "/api/training/reasons-ab", json=_rt.body({"checked": checked, "contenders": contenders, "held_out_ids": held_out_ids, "language": language, "noise_band": noise_band}))


