    all_lines: Annotated[Optional[bool], Field(description='Train an A/B arm on every line it has, not only the lines every reasoning arm covers. Default: false.')] = None,
    arm: Annotated[Optional[str], Field(description='What the student learns to write (#4642): the checked transcription alone, with a palaeographer\'s reasons, with its thinking, or a review of a draft. Reasons come from the episode ledger (training.reasons); the answer is always the checked text. One of: answer, why, thinking, review. Default: "answer".')] = None,
    base_licence: Annotated[Optional[str], Field(description="The base's licence, carried on the card; none: from Fichero's list of vision bases, or 'not checked'.")] = None,
    base_repo: Annotated[Optional[str], Field(description='The bf16 base on the Hub: any image-text-to-text model (Qwen3-VL 8B by default; Qwen2.5-VL 7B, chandra and others are valid). Default: "Qwen/Qwen3-VL-8B-Instruct".')] = None,
    display_name: Annotated[Optional[str], Field(description='Display Name.')] = None,
    epochs: Annotated[Optional[int], Field(description='Epochs. Default: 2.')] = None,
    flavor: Annotated[Optional[str], Field(description='Hugging Face hardware; none chooses the cheapest that fits a 7B LoRA.')] = None,
    held_out_ids: Annotated[Optional[list[Any]], Field(description='Pages kept home as the test; never sent.')] = None,
    keep_merged_here: Annotated[Optional[bool], Field(description="Also keep the merged Hugging Face weights on this Mac (~17 GB for 8B); they are always kept in the job's bucket. Default: false.")] = None,
    language: Annotated[Optional[str], Field(description="The pages' language, given to the student as the line reader gives it.")] = None,
    max_trace_cer: Annotated[Optional[float], Field(description="A palaeographer's reasons are kept only where its own reading of the line is within this CER of the checked one. Default: 0.1.")] = None,
    name: Annotated[Optional[str], Field(description='A short name: the model lands as fichero-trained/<name>. Default: "student".')] = None,
    not_for_release: Annotated[Optional[bool], Field(description='The trained model may not be released. Default: true.')] = None,
    pages_may_leave: Annotated[Optional[bool], Field(description="The person's yes for these pages to go to Hugging Face. Default: false.")] = None,
