def fichero_workflow_execution_delete_thread(
    *,
    thread_id: Annotated[str, Field(description='Thread Id')],
) -> Any:
    'Delete Thread\n\nDelete a workflow execution thread and its checkpoints.\n\nRemoves all checkpoint data for the specified thread, and the run\nRECORD (``workflow_runs`` row + its events) through the SAME audited\n``workflow_run.delete`` action the bulk route uses (#4960) — a single\ndelete was, before this, the one run operation NOT recorded by the\naction layer. The checkpoint-specific work (cancellation signal,\ncheckpoint deletion) stays here; it is a thread/execution-engine\nconcern the bulk action deliberately does not touch.\n\nArgs:\n    thread_id: Thread ID to delete\n\nReturns:\n    Success message\n\nRaises:\n    404: Thread not found\n\nRoute: DELETE /api/workflow-execution/threads/{thread_id} (toolset `workflow-execution`; changes data, as the agent account when one exists).'
    return _rt.call("DELETE", f"/api/workflow-execution/threads/{thread_id}")


def fichero_workflow_execution_cancel(
    *,
    thread_id: Annotated[str, Field(description='Thread Id')],
) -> Any:
    'Cancel Workflow\n\nCancel a workflow run in ANY non-terminal state (#1127, #4316, #4317).\n\n- A running (or about-to-run ``accepted``) worker is signalled through\n  BOTH the registry flag and the shared cancellation event\n  (execution.cancellation), which the runner\'s event loop AND the\n  per-file fan-out check — so cancel reaches a run even after registry\n  eviction, and stops multi-file nodes at the next file boundary.\n- A ``paused`` run has no live coroutine to signal — its worker returned\n  at the pause boundary — so cancel settles it directly: run row →\n  cancelled, processing documents → pending (#4315).\n\nPartial results (artifacts, entities, claims already written) are\nintentionally preserved. Idempotent: terminal runs return\n``status="already_terminal"``; unknown threads ``status="not_running"``.\n\nRoute: POST /api/workflow-execution/threads/{thread_id}/cancel (toolset `workflow-execution`; changes data, as the agent account when one exists).'
    return _rt.call("POST", f"/api/workflow-execution/threads/{thread_id}/cancel")


