def fichero_workflow_execution_get_thread_status(
    *,
    thread_id: Annotated[str, Field(description='Thread Id')],
    view: Annotated[Optional[str], Field(description="`summary` leaves out the run's whole state (hundreds of KB for a fanned-out run) and keeps `progress`: the current step and per-file outcome counts (#5401).")] = None,
) -> Any:
    "Get Thread Status\n\nGet status of a workflow execution thread.\n\nRetrieves the current state and checkpoint information for a thread, and the run's\nprogress (the current step, files done, succeeded, failed and cancelled per fanned-out\nstep, the first failures by file), counted from the state and the checkpoint's pending\nwrites so a running fan-out is counted as it goes.\n\nArgs:\n    thread_id: Thread ID\n    view: `full` (the whole state) or `summary` (progress only)\n\nReturns:\n    Current execution status\n\nRaises:\n    404: Thread not found\n\nRoute: GET /api/workflow-execution/threads/{thread_id}/status (toolset `workflow-execution`; reads)."
    return _rt.call("GET", f"/api/workflow-execution/threads/{thread_id}/status", params={"view": view})


